import {
  BaseGatewayAdapter,
  type GatewayMetadata,
  type GatewayField,
  type InitiateParams,
  type InitiateResult,
  type VerifyResult,
  type Credentials,
  type GatewayContext,
} from '../base';
import { gwJson } from '../kit/http';
import { hmacHex } from '../../lib/hash';

const SANDBOX_URL = "https://test-payment.momo.vn";
const LIVE_URL = "https://payment.mo-mo.vn";

const SLUG = "momo";

export class MomoGateway extends BaseGatewayAdapter {
  metadata(): GatewayMetadata {
    return {
      name: "MoMo Wallet",
      slug: "momo",
      version: '1.0.0',
      description: "MoMo E-wallet payment integration for Vietnam",
      author: 'OwnPay Gateway Plugin Suite (AGPLv3) — EdgePay port',
      type: 'gateway',
      supported_currencies: ["VND"],
      capabilities: ["verification", "webhook"],
    };
  }

  fields(): GatewayField[] {
    return [
      { name: "partner_code", label: "Partner Code", type: "text" as const, required: true },
      { name: "access_key", label: "Access Key", type: "text" as const, required: true },
      { name: "secret_key", label: "Secret Key", type: "password" as const, required: true },
    ];
  }

  async initiate(params: InitiateParams, credentials: Credentials, _ctx?: GatewayContext): Promise<InitiateResult> {
    const partnerCode = String(credentials["partner_code"] ?? '');
    const accessKey = String(credentials["access_key"] ?? '');
    const secretKey = String(credentials["secret_key"] ?? '');
    const mode = String(credentials.mode ?? 'sandbox');
    const baseUrl = (String(mode) === String("live")) ? (LIVE_URL) : (SANDBOX_URL);
    const amountVal = (params.amount ?? '');
    const amountInt = Math.trunc(Number(String(Math.round(Number(String(amountVal)) * 1))));
    const amountStr = String(amountInt);
    const orderId = (params.trx_id ?? '');
    const requestId = `req_${String(orderId)}`;
    const orderInfo = `Order Payment ${String(orderId)}`;
    const extraData = "";
    const requestType = "captureWallet";
    const rawHash = `accessKey=${String(accessKey)}&amount=${String(amountStr)}&extraData=${String(extraData)}&ipnUrl={$params['redirect_url']}&orderId=${String(orderId)}&orderInfo=${String(orderInfo)}&partnerCode=${String(partnerCode)}&redirectUrl={$params['redirect_url']}&requestId=${String(requestId)}&requestType=${String(requestType)}`;
    const signature = await hmacHex('SHA-256', String(rawHash), String(secretKey));
    const payload = { ["partnerCode"]: partnerCode, ["partnerName"]: "OwnPay", ["storeId"]: "OwnPayStore", ["requestId"]: requestId, ["amount"]: amountInt, ["orderId"]: orderId, ["orderInfo"]: orderInfo, ["redirectUrl"]: (params.redirect_url ?? ''), ["ipnUrl"]: (params.redirect_url ?? ''), ["lang"]: "vi", ["extraData"]: extraData, ["requestType"]: requestType, ["signature"]: signature };
    const res = await gwJson({
      url: `${String(baseUrl)}/v2/gateway/api/create`,
      method: 'POST',
      headers: { ["Content-Type"]: "application/json" },
      body: JSON.stringify(payload),
      timeoutMs: 15000,
    });
    if (res.data === null) throw new Error(`${SLUG}: invalid response`);
    const d = res.data as Record<string, unknown>;
    const payUrl = String(((d) as Record<string, unknown>)["payUrl"] ?? '');
    return {
          redirect_url: (payUrl || undefined) as string | undefined,
          session_id: (orderId || undefined) as string | undefined,
        };
  }

  async verify(_callbackData: Record<string, unknown>, credentials: Credentials, _ctx?: GatewayContext): Promise<VerifyResult> {
    const mode = String(credentials.mode ?? 'sandbox');
    const baseUrl = (String(mode) === String("live")) ? (LIVE_URL) : (SANDBOX_URL);
    const res = await gwJson({
      url: `${String(baseUrl)}/v2/gateway/api/query`,
      method: 'POST',
      timeoutMs: 15000,
    });
    const d = res.data as Record<string, unknown>;
    if (res.data === null) {
          return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
        }
    const resultCode = String((((d) as Record<string, unknown>)["resultCode"] ?? -1) ?? '');
    const ok = String(resultCode) === String(0);
    return {
          success: ok,
          gateway_trx_id: String(""),
          status: (ok ? 'completed' : 'failed') as VerifyResult['status'],
      amount: null,
        };
  }

  async verifyWebhook(_input: { rawBody: string; headers: Record<string, string>; credentials: Credentials }): Promise<boolean> {
    // PORT-REVIEW: upstream webhook scheme not extracted — fail-closed.
    return false;
  }
}
